head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > createPopup]<br/>지정된 파라미터값에 맞게 팝업을 생성합니다.<br/>이 메소드는 향후 제거(Deprecated)될 예정입니다. openPopup() 메소드 사용을 권장합니다.",
    "validation" : [
        "파라미터가 많아 팝업 후 일부만 검증합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_createPopup_onclick = function () {
    let modal = par_modal.getValue();

    WebSquare.util.createPopup(
        "createPopup_1",
        "window",
        "테스트 팝업",
        "width:600px;height:350px;top:100px;left:100px;",
        true,
        modal,
        "/sample/common_link/util_createPopup_1.xml",
        "WebSquare1.xml",
        undefined,
        "map",
        undefined
    );


    // 팝업 생성 검증
    setTimeout(function () {
        let result = [];

        let popupEl = document.querySelector("div[id='createPopup_1']");

        result.push("팝업 존재 : " + (popupEl ? "PASS" : "FAIL"));

        result.push("style.left: " +popupEl.style.left+")");
        result.push("style.top: " +popupEl.style.top+")");
        result.push("style.width: " +popupEl.style.width+")");
        result.push("style.height: " +popupEl.style.height+")");
        result.push("textContent: " +popupEl.textContent+")");

        if (modal === 'true') {
            let modalOverlay = document.querySelector(".w2modalopenedbody");
            result.push("모달 배경 존재 : " + (modalOverlay ? "PASS" : "FAIL"));
        } else {
            let modalOverlay = document.querySelector(".w2modalopenedbody");
            result.push("모달 배경 미존재 : " + (!modalOverlay ? "PASS" : "FAIL"));
        }

        let iframeEl = popupEl ? popupEl.querySelector("iframe") : null;
        result.push("iFrame 존재 : " + (iframeEl ? "PASS" : "FAIL"));

        if (iframeEl) {
            let iframeDoc = iframeEl.contentDocument || iframeEl.contentWindow.document;
            let textboxEl = iframeDoc.querySelector("div[id*='createPopup_textbox1']");
            result.push("팝업 내 컴포넌트 존재 : " + (textboxEl ? "PASS" : "FAIL"));
        }

        wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));     
    }, 500);
}
